                     headers={"Content-Type": "application/json", "Idempotency-Key": "pay-" + inv},
                     body=json.dumps({"invoice": inv, "amount_cents": int(rows[inv]["amount_cents"])}))
    print(inv, res["status"], res["text"][:160])"}

